('553','middle-east-country-profiles','palestine-unrwa-reference','WAFA সম্পর্কে উৎস-বক্তব্য','উৎসে ফিলিস্তিনের জাতীয় বার্তা সংস্থার নাম WAFA বলা হয়েছে।','source_attributed','high','a5a47b0ca36734b5d859006b89da5d5d88090546f94a863fe21f5901520bfc86')) INSERT INTO public.gk_facts (book_id,chapter_id,topic_id,title,fact_text,explanation,source_page,source_section,source_excerpt,importance,confidence,canonical_hash) SELECT b.id,c.id,t.id,d.title,d.body,CASE d.status WHEN 'verified' THEN 'Direct official corroboration is recorded in the batch verification ledger.' WHEN 'conflicting' THEN 'The printed source is retained with a directly cited historical-chronology caveat.' ELSE 'Source-attributed material retained after ordered image review; it is not silently updated as a current assertion.' END,d.page::integer,d.title,d.body,3,d.confidence::confidence_level,d.hash FROM d JOIN public.books b ON b.title='Jubayer''s GK' JOIN public.chapters c ON c.book_id=b.id AND c.slug=d.chapter_slug JOIN public.topics t ON t.chapter_id=c.id AND t.slug=d.topic_slug ON CONFLICT (canonical_hash) DO UPDATE SET fact_text=EXCLUDED.fact_text,explanation=EXCLUDED.explanation,confidence=EXCLUDED.confidence;
WITH d(page,chapter_slug,topic_slug,title,body,confidence,hash) AS (VALUES ('549','myanmar-rohingya-reference','myanmar-rohingya-past-questions','মিয়ানমার ও রোহিঙ্গা — বিগত প্রশ্ন','উৎসে University of Dhaka, BCS, এবং অন্যান্য পরীক্ষার মিয়ানমার/রোহিঙ্গা বিষয়ক প্রশ্ন আছে।
